run_script %{"script" => "local result, err = create_issue({
  title = "Reservations spec missing Test Assertions section",
  description = "The spec for the Reservations component does not include a Test Assertions section. Without it there is no documented, agreed-upon set of assertions to drive or validate test coverage for Reservations, so implementation and QA have no spec-level source of truth for what the tests should check. Please add a Test Assertions section to the Reservations spec enumerating the expected behaviors/assertions to test.",
  severity = "warning",
  scope = "app"
})
if result == nil then return "failed: " .. err.message end
return result"}

